CREATE EXTENSION IF NOT EXISTS "uuid-ossp"; CREATE TABLE IF NOT EXISTS public.prescription_approval_workflows ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE, prescription_id UUID NOT NULL REFERENCES prescriptions(id) ON DELETE CASCADE, patient_id UUID NOT NULL REFERENCES patients(id) ON DELETE CASCADE, initiated_by UUID NOT NULL REFERENCES profiles(id) ON DELETE RESTRICT, status TEXT NOT NULL DEFAULT 'initiated' CHECK (status IN ('initiated', 'pending_approval', 'pending_clarification', 'approved', 'dispensed', 'completed', 'rejected', 'cancelled')), current_step INTEGER NOT NULL DEFAULT 1, approved_by UUID REFERENCES profiles(id) ON DELETE SET NULL, approved_at TIMESTAMPTZ, rejection_reason TEXT, rejected_at TIMESTAMPTZ, dur_check_passed BOOLEAN DEFAULT NULL, dur_warnings TEXT[], clarification_notes TEXT, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); ALTER TABLE public.prescription_approval_workflows ENABLE ROW LEVEL SECURITY; CREATE POLICY "prescription_approval_hospital_scope" ON public.prescription_approval_workflows USING ( hospital_id = (SELECT hospital_id FROM profiles WHERE id = auth.uid()) );